import{_ as a,o as t,c as o,a2 as l}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Atajos de teclado y gestos","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/hotkeys.md","filePath":"es-ES/user-guide/hotkeys.md","lastUpdated":1790959149000}'),n={name:"es-ES/user-guide/hotkeys.md"};function r(s,e,i,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="atajos-de-teclado-y-gestos" tabindex="-1">Atajos de teclado y gestos <a class="header-anchor" href="#atajos-de-teclado-y-gestos" aria-label="Permalink to &quot;Atajos de teclado y gestos&quot;">​</a></h1><p>Lertaro adopta una filosofía de interacción centrada en el teclado, complementada con prácticos gestos de ratón y navegación rápida en cascada. Excepto las teclas fijas, todos los atajos globales y de la aplicación se pueden personalizar en <a href="./settings/hotkeys-page.html"><strong>Configuración → Atajos de teclado</strong></a>.</p><h2 id="_1-tabla-resumen-de-atajos-globales" tabindex="-1">1. Tabla resumen de atajos globales <a class="header-anchor" href="#_1-tabla-resumen-de-atajos-globales" aria-label="Permalink to &quot;1. Tabla resumen de atajos globales&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Acción</th><th style="text-align:left;">Atajo predeterminado</th><th style="text-align:left;">Descripción y detalles de interacción</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Mostrar/Ocultar Ventana rápida</strong></td><td style="text-align:left;">Doble pulsación de <code>Ctrl</code></td><td style="text-align:left;">Configurable en modo doble pulsación o combinación estándar (p. ej. <code>Alt+Space</code>, <code>Win+Space</code>). Una doble pulsación son dos pulsaciones del <strong>mismo</strong> modificador, soltadas con <strong>100–300 ms</strong> de diferencia: la <code>Ctrl</code> izquierda y la derecha son teclas distintas, y cualquier otra tecla pulsada en medio reinicia el conteo. En la forma de doble pulsación el modificador nunca se consume, así que los atajos normales del estilo <code>Ctrl</code>+<code>C</code> siguen funcionando. Si se activa <strong>Abrir el panel principal de forma predeterminada</strong>, este atajo abre la Ventana principal: al mostrarla por primera vez solo la lleva al primer plano y le da el foco una vez; si está visible pero inactiva la vuelve a activar, y si ya está activa la cierra al pulsar de nuevo. No se mantiene automáticamente siempre encima.</td></tr><tr><td style="text-align:left;"><strong>Salto rápido (Quick Jump)</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">En cuadros de diálogo, salta directamente a la carpeta consultada recientemente en exploradores o en el Panel rápido.</td></tr><tr><td style="text-align:left;"><strong>Menú de Navegación rápida</strong></td><td style="text-align:left;">Sin valor predeterminado</td><td style="text-align:left;">Un atajo global opcional abre el menú de Navegación rápida en cascada. Desde el escritorio o una aplicación normal usa el contexto del escritorio; en el Explorador de archivos y los cuadros de diálogo nativos usa el contexto de la ventana activa. Los exploradores y los cuadros de diálogo siguen permitidos aunque la protección normal de primer plano suprima los atajos globales.</td></tr><tr><td style="text-align:left;"><strong>Seleccionar elemento siguiente</strong></td><td style="text-align:left;"><code>Ctrl+N</code> o <code>↓</code></td><td style="text-align:left;">Mueve el resaltado hacia abajo. En el Panel rápido se desplaza fluidamente entre grupos. En el Panel de inicio rápido, las flechas siguen la cuadrícula visible: <strong>←</strong> y <strong>→</strong> atraviesan los límites de las filas, mientras <strong>↑</strong> y <strong>↓</strong> buscan el elemento más cercano de la misma columna en la dirección correspondiente, incluso entre grupos. Si no existe ningún elemento de esa columna en toda la dirección adyacente, la selección permanece donde está. Con el Panel de inicio rápido visible y la consulta vacía, <code>Ctrl+N</code> recorre la siguiente fuente y vuelve a la primera al llegar al final.</td></tr><tr><td style="text-align:left;"><strong>Seleccionar elemento anterior</strong></td><td style="text-align:left;"><code>Ctrl+P</code> o <code>↑</code></td><td style="text-align:left;">Mueve el resaltado hacia arriba. En el Panel rápido también se desplaza entre grupos. En el Panel de inicio rápido, las flechas siguen la cuadrícula visible: <strong>←</strong> y <strong>→</strong> atraviesan los límites de las filas, mientras <strong>↑</strong> y <strong>↓</strong> buscan el elemento más cercano de la misma columna en la dirección correspondiente, incluso entre grupos. Si no existe ningún elemento de esa columna en toda la dirección adyacente, la selección permanece donde está. Con el Panel de inicio rápido visible y la consulta vacía, <code>Ctrl+P</code> recorre la fuente anterior y vuelve a la última al llegar al principio.</td></tr><tr><td style="text-align:left;"><strong>Saltar a resultados 1–9</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">Modificador personalizable. Aparecen distintivos numéricos junto a los resultados para apertura instantánea. El número indica la N.ª fila seleccionable <strong>a partir de la primera fila visible</strong>, así que los distintivos se renumeran al desplazar; la <code>0</code> no está asignada. El panel de Inicio rápido es la excepción: asigna <code>1</code>–<code>9</code>, <code>0</code> y <code>A</code>–<code>Z</code> para hasta 36 mosaicos.</td></tr><tr><td style="text-align:left;"><strong>Abrir Menú de acciones</strong></td><td style="text-align:left;"><code>Ctrl+O</code> o <code>→</code></td><td style="text-align:left;">Despliega el menú contextual de acciones (copiar ruta, propiedades, ejecutar como admin, operaciones de archivo, etc.). Funciona en la Ventana rápida y en la tarjeta incrustada <strong>fuera</strong> de los diálogos de archivos; la Ventana principal abre el mismo menú con el clic derecho o la tecla <code>Apps</code> (<code>Shift+F10</code>).</td></tr><tr><td style="text-align:left;"><strong>Autocompletar desde selección</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">Rellena la barra de búsqueda con el nombre o ruta completa del elemento seleccionado para refinamiento.</td></tr><tr><td style="text-align:left;"><strong>Vista previa instantánea QuickLook</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">Abre/cierra el panel lateral de vista previa (imágenes, documentos, reproducción de audio/vídeo, árboles de carpetas). Disponible en la Ventana rápida, la Ventana principal y el Panel rápido, no en la tarjeta incrustada; hacer clic central en una fila previsualizable alterna el mismo panel.</td></tr><tr><td style="text-align:left;"><strong>Término de búsqueda anterior</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">Retrocede por el historial reciente de búsquedas.</td></tr><tr><td style="text-align:left;"><strong>Término de búsqueda siguiente</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">Avanza por el historial reciente de búsquedas.</td></tr><tr><td style="text-align:left;"><strong>Eliminar término de historial</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">Elimina la palabra clave mostrada actualmente del historial de búsqueda.</td></tr><tr><td style="text-align:left;"><strong>Abrir Ventana principal</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">Abre la ventana principal de gran tamaño manteniendo la búsqueda actual.</td></tr><tr><td style="text-align:left;"><strong>Abrir ventana LocalSend</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">Abre la ventana de transferencia inalámbrica LocalSend para enviar archivos o texto a otros dispositivos.</td></tr><tr><td style="text-align:left;"><strong>Fijar ventana (Mantener visible)</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">Bloquea la ventana abierta al perder el foco (ideal para pegar búsquedas de varias fuentes).</td></tr><tr><td style="text-align:left;"><strong>Mostrar/Ocultar Panel rápido</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">Acopla el panel rápido junto a la ventana activa con archivos recientes, favoritos y espacios de trabajo.</td></tr></tbody></table><h3 id="busqueda-en-linea-vacia-en-dialogos-de-archivos" tabindex="-1">Búsqueda en línea vacía en diálogos de archivos <a class="header-anchor" href="#busqueda-en-linea-vacia-en-dialogos-de-archivos" aria-label="Permalink to &quot;Búsqueda en línea vacía en diálogos de archivos&quot;">​</a></h3><p>Cuando un cuadro de búsqueda en línea está integrado en un diálogo de archivos nativo y la consulta está vacía, la lista muestra primero el grupo <strong>Directorio anterior</strong>. Si está activado <strong>Mostrar las carpetas abiertas actualmente en la búsqueda integrada</strong>, también muestra el grupo <strong>Carpetas abiertas actualmente</strong>, recopilado desde los exploradores compatibles. Se excluye la carpeta actual del diálogo, las rutas duplicadas se unifican, los grupos vacíos permanecen ocultos y los encabezados de grupo no muestran insignias de atajos. La opción está activada de forma predeterminada y se puede cambiar en <a href="./settings/general.html"><strong>Configuración → General → Sistema</strong></a>. Este comportamiento solo se aplica a la búsqueda en línea de los diálogos de archivos; las ventanas Rápida y Completa no cambian.</p><h3 id="invocacion-y-traspaso-del-foco-en-la-ventana-incrustada" tabindex="-1">Invocación y traspaso del foco en la Ventana incrustada <a class="header-anchor" href="#invocacion-y-traspaso-del-foco-en-la-ventana-incrustada" aria-label="Permalink to &quot;Invocación y traspaso del foco en la Ventana incrustada&quot;">​</a></h3><p>Una tarjeta acoplada en un diálogo de archivos nativo <strong>no roba el teclado</strong> a propósito: el diálogo conserva el foco, así que sigues escribiendo en su propio campo de nombre de archivo mientras la tarjeta refleja la consulta. Los gestos que mueven el cursor son:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Gesto</th><th style="text-align:left;">Efecto</th><th style="text-align:left;">Condiciones</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Escribir una letra o un dígito</strong></td><td style="text-align:left;">Invoca la tarjeta y lleva ese primer carácter al cuadro de búsqueda; las pulsaciones siguientes siguen entrando</td><td style="text-align:left;">Solo pulsaciones reales: la entrada sintetizada por herramientas de automatización pasa intacta, y no se captura nada mientras haya un menú contextual o del sistema abierto</td></tr><tr><td style="text-align:left;"><strong>Doble pulsación de <code>Ctrl</code></strong> (o el atajo de invocación que configures)</td><td style="text-align:left;">Coloca el cursor en el cuadro de búsqueda propio de la tarjeta. Cuando el cuadro ya tiene el cursor y la consulta está vacía, en cambio borra la consulta y devuelve el foco al campo del diálogo, manteniendo la tarjeta abierta</td><td style="text-align:left;">Es el mismo atajo que en cualquier otra parte, así que reasignarlo en <a href="./settings/hotkeys-page.html"><strong>Configuración → Atajos de teclado</strong></a> también mueve esto. Un diálogo de archivos sigue permitido incluso cuando una lista negra o la pantalla completa suelen silenciar los atajos globales</td></tr><tr><td style="text-align:left;"><strong><code>Escape</code></strong></td><td style="text-align:left;">Mientras el <strong>diálogo</strong> tiene el teclado, la tarjeta se cierra. Mientras lo tiene la <strong>tarjeta</strong>, se borra la consulta y el foco vuelve al diálogo (en un diálogo de archivos) o la tarjeta se cierra (acoplada sobre una ventana normal del Explorador)</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong><code>Backspace</code></strong> en un cuadro vacío</td><td style="text-align:left;">Abandona la búsqueda exactamente igual que <code>Escape</code></td><td style="text-align:left;">Solo cuando la tarjeta tiene el cursor; mientras el diálogo tiene el teclado la tecla solo edita la consulta de la tarjeta</td></tr><tr><td style="text-align:left;"><strong><code>Enter</code></strong> en un cuadro vacío</td><td style="text-align:left;">Abandona la búsqueda como <code>Escape</code></td><td style="text-align:left;">Solo cuando la tarjeta tiene el cursor: mientras el diálogo tiene el teclado, <code>Enter</code> abre la fila de navegación resaltada</td></tr><tr><td style="text-align:left;"><strong><code>Tab</code></strong></td><td style="text-align:left;">Siempre queda como el recorrido de controles propio del diálogo, así que llega a la tarjeta con el atajo de invocación</td><td style="text-align:left;"></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Dentro de un diálogo de archivos el menú de acciones no está disponible para la tarjeta (<code>Ctrl+O</code>, <code>→</code> y el clic derecho no hacen nada ahí), y tampoco se ofrece la vista previa con <code>Alt+P</code>. El ratón sigue funcionando sobre las filas: el <strong>clic izquierdo</strong> abre el resultado resaltado, <strong><code>Ctrl</code>+clic</strong> lo abre como administrador, una fila se puede <strong>arrastrar hacia fuera</strong> hacia el diálogo y simplemente <strong>pasar el ratón por encima</strong> mueve la selección, que el explorador anfitrión refleja.</p></div><h2 id="_2-icono-de-busqueda-y-gestos-de-raton" tabindex="-1">2. Icono de búsqueda y gestos de ratón <a class="header-anchor" href="#_2-icono-de-busqueda-y-gestos-de-raton" aria-label="Permalink to &quot;2. Icono de búsqueda y gestos de ratón&quot;">​</a></h2><p>El pequeño logotipo en la barra de búsqueda no es solo estético: ofrece múltiples gestos rápidos:</p><h3 id="gestos-del-icono-en-la-ventana-rapida" tabindex="-1">Gestos del icono en la Ventana rápida <a class="header-anchor" href="#gestos-del-icono-en-la-ventana-rapida" aria-label="Permalink to &quot;Gestos del icono en la Ventana rápida&quot;">​</a></h3><ul><li><strong>Clic izquierdo</strong>: Despliega el menú contextual principal (Mostrar ventana principal, Cambiar atajo, Configuración, Acerca de, Salida limpia, Salir). &quot;Mostrar ventana principal&quot; transfiere tu búsqueda activa.</li><li><strong>Clic izquierdo y arrastrar</strong>: Arrastra la barra de búsqueda para reubicarla. <strong>Mantener <code>Ctrl</code> mientras arrastras</strong> bloquea el movimiento al <strong>eje vertical</strong>, manteniendo la alineación horizontal intacta.</li><li><strong>Clic derecho</strong>: Restablece instantáneamente la Ventana rápida a su posición central predeterminada en pantalla sin alterar dimensiones.</li><li><strong>Clic central</strong>: Alterna el estado &quot;Fijar ventana&quot;. El logotipo se ilumina mientras está fijada.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Las coordenadas recordadas para la Ventana rápida son <strong>coordenadas relativas proporcionales</strong> a ese monitor. Al invocarla en otra pantalla con distinta resolución o escala DPI, Lertaro recalcula la posición automáticamente dentro de los límites visibles.</p></div><h3 id="iconos-en-la-ventana-incrustada-y-ventana-principal" tabindex="-1">Iconos en la Ventana incrustada y Ventana principal <a class="header-anchor" href="#iconos-en-la-ventana-incrustada-y-ventana-principal" aria-label="Permalink to &quot;Iconos en la Ventana incrustada y Ventana principal&quot;">​</a></h3><ul><li><strong>Ventana incrustada</strong>: Al incrustarse en diálogos nativos (Abrir/Guardar/Examinar), hacer clic izquierdo en el icono abre el menú de <a href="#3-navegacion-rapida-activadores-de-raton"><strong>Navegación rápida</strong></a>; desactivado en el Explorador ordinario. Arrastrar el icono mueve la propia tarjeta, y el desplazamiento se vuelve a aplicar en cada acoplamiento posterior.</li><li><strong>Ventana principal</strong>: Al hacer clic izquierdo en el icono se abre el menú contextual; <strong>Mostrar ventana principal</strong> se oculta porque la ventana ya está abierta. El clic central alterna el estado de fijación de la ventana.</li></ul><h3 id="gestos-del-cuadro-de-busqueda-ventana-rapida" tabindex="-1">Gestos del cuadro de búsqueda (Ventana rápida) <a class="header-anchor" href="#gestos-del-cuadro-de-busqueda-ventana-rapida" aria-label="Permalink to &quot;Gestos del cuadro de búsqueda (Ventana rápida)&quot;">​</a></h3><ul><li><strong>Rueda del ratón sobre el cuadro</strong>: Retrocede o avanza por los términos de búsqueda recientes, la misma navegación que <code>Alt+Up</code> / <code>Alt+Down</code> y sin quitar la mano del ratón.</li><li><strong>Clic central en el cuadro</strong>: Elimina la entrada del historial que se está mostrando. Este gesto es fijo y no es la asignación configurable de <code>Ctrl+Delete</code>.</li><li><strong>Escribir en cualquier momento</strong> termina la sesión del historial, así que el siguiente clic de rueda empieza de nuevo desde tu consulta actual. El historial no da la vuelta: el término más antiguo se detiene ahí, y el más reciente devuelve la consulta desde la que empezaste.</li></ul><h3 id="icono-de-la-bandeja-del-sistema" tabindex="-1">Icono de la bandeja del sistema <a class="header-anchor" href="#icono-de-la-bandeja-del-sistema" aria-label="Permalink to &quot;Icono de la bandeja del sistema&quot;">​</a></h3><ul><li><strong>Clic izquierdo</strong>: Alterna la Ventana rápida, exactamente igual que el atajo de invocación.</li><li><strong>Clic derecho</strong> (o un segundo clic, ya que no existe controlador de doble clic): Abre el menú en el cursor: Mostrar ventana principal, Enviar a otros dispositivos (solo mientras LocalSend esté activo), Desactivar/Activar atajos, Configuración, Acerca de, Salida limpia (solo cuando Lertaro es el único proceso en ejecución) y Salir.</li><li><strong>Ocultar icono de la bandeja del sistema</strong> (<a href="./settings/general.html"><strong>Configuración → General → Sistema</strong></a>) quita el icono, pero nunca el menú del icono dentro de la ventana. Mientras los atajos estén desactivados desde ese menú, el icono se muestra de nuevo a la fuerza para que no puedas quedarte fuera.</li></ul><h2 id="_3-navegacion-rapida-activadores-de-raton" tabindex="-1">3. Navegación rápida (Activadores de ratón) <a class="header-anchor" href="#_3-navegacion-rapida-activadores-de-raton" aria-label="Permalink to &quot;3. Navegación rápida (Activadores de ratón)&quot;">​</a></h2><p>La Navegación rápida te permite acceder a directorios frecuentes y archivos recientes únicamente con clics de ratón, sin teclear.</p><p>También puedes asignar un atajo de teclado global opcional en <a href="./settings/hotkeys-page.html"><strong>Configuración → Atajos de teclado</strong></a>. Desde el escritorio o una aplicación normal abre el menú con el contexto del escritorio; en el Explorador de archivos y los cuadros de diálogo nativos usa el contexto de la ventana activa.</p><h3 id="entornos-compatibles" tabindex="-1">Entornos compatibles <a class="header-anchor" href="#entornos-compatibles" aria-label="Permalink to &quot;Entornos compatibles&quot;">​</a></h3><ul><li><strong>Espacio vacío del Escritorio</strong>: Clic central (o doble clic izquierdo opcional) para abrir el menú. Al hacer clic en una carpeta o archivo se abre directamente.</li><li><strong>Explorador de archivos</strong>: Clic central en zonas vacías del Explorador; al hacer clic en un elemento, la ventana navega directamente a esa carpeta.</li><li><strong>Exploradores de terceros</strong>: Clic central en la lista de archivos de Directory Opus, Total Commander, XYplorer, Files y One Commander (ver <a href="./file-manager-support.html"><strong>Exploradores de archivos compatibles</strong></a>).</li><li><strong>Diálogos de archivo</strong>: Clic central o clic en el icono incrustado dentro de diálogos Abrir/Guardar para saltar a la carpeta de destino sin confirmar accidentalmente.</li></ul><h3 id="estructura-del-menu-en-cascada" tabindex="-1">Estructura del menú en cascada <a class="header-anchor" href="#estructura-del-menu-en-cascada" aria-label="Permalink to &quot;Estructura del menú en cascada&quot;">​</a></h3><p>Impulsado por el plugin <strong>Folder Cascader</strong>:</p><ol><li><strong>Carpetas abiertas actualmente</strong>: Agrupa y desduplica carpetas activas de todos los exploradores abiertos.</li><li><strong>Favoritos e Historial</strong>: Muestra elementos marcados con estrella e historial de visitas recientes.</li><li><strong>Categorías personalizadas</strong>: Configura submenús anidados en <strong>Configuración → Plugins → Folder Cascader</strong> (p. ej. <code>Trabajo/ProyectoA</code>).</li><li><strong>Añadir carpeta rápida (Botón <code>+</code>)</strong>: Cada encabezado de submenú cuenta con un botón <code>+</code> para guardar el directorio activo directamente en esa categoría.</li></ol><h2 id="_4-teclas-fijas-basicas-no-configurables" tabindex="-1">4. Teclas fijas básicas (No configurables) <a class="header-anchor" href="#_4-teclas-fijas-basicas-no-configurables" aria-label="Permalink to &quot;4. Teclas fijas básicas (No configurables)&quot;">​</a></h2><p>Para garantizar un comportamiento coherente y determinista, las siguientes teclas actúan igual en todas las configuraciones:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tecla</th><th style="text-align:left;">Contexto</th><th style="text-align:left;">Comportamiento estándar</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Lista de resultados</td><td style="text-align:left;">Abre el elemento seleccionado (archivo, carpeta, app o acción). En la Ventana principal abre <strong>todas</strong> las filas seleccionadas. En un cuadro de búsqueda incrustado vacío, en cambio, abandona la búsqueda: no hay ninguna mejor coincidencia que abrir.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Lista de resultados</td><td style="text-align:left;">Muestra y selecciona el elemento en el Explorador de archivos de Windows.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Lista de resultados</td><td style="text-align:left;">Ejecuta la aplicación seleccionada con privilegios de administrador.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Ventana rápida</td><td style="text-align:left;">Oculta la ventana. Nunca vacía el cuadro en esa pulsación: la consulta se conserva o se descarta según <strong>Mantener el contenido del cuadro de búsqueda al cerrar</strong>.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Ventana principal</td><td style="text-align:left;">Borra la consulta y vuelve a enfocar el cuadro; cierra la ventana cuando el cuadro ya está vacío, o directamente cuando <strong>Mantener el contenido del cuadro de búsqueda al cerrar</strong> está activado (así no tienes que pulsarlo dos veces en vano).</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Tarjeta incrustada</td><td style="text-align:left;">Consulta <strong>Invocación y traspaso del foco en la Ventana incrustada</strong> más arriba: cierra la tarjeta mientras el diálogo tiene el teclado y devuelve el foco mientras lo tiene la tarjeta.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Menú de acciones</td><td style="text-align:left;">Una pulsación por nivel: borra el filtro de acciones, luego sale del submenú y después abandona el menú y restaura la consulta original.</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">Menú de acciones</td><td style="text-align:left;">Sale del menú de acciones hacia la lista de resultados cuando el filtro está vacío.</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> Flechas</td><td style="text-align:left;">Menú de acciones</td><td style="text-align:left;">Flecha izquierda vuelve al menú superior; flecha derecha entra en submenús. <code>Tab</code> entra en un submenú también, salvo que la hayas asignado al atajo de elemento siguiente/anterior.</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">Tarjeta incrustada</td><td style="text-align:left;">Se consume para que el foco no pueda salir del cuadro de búsqueda, mientras que <code>Tab</code> dentro del diálogo sigue recorriendo sus propios controles como siempre.</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">Menú de acciones</td><td style="text-align:left;">Entra en el submenú resaltado, salvo que hayas asignado <code>Tab</code> al atajo de elemento siguiente/anterior, que gana.</td></tr><tr><td style="text-align:left;"><code>Apps</code> / <code>Shift+F10</code></td><td style="text-align:left;">Ventana principal</td><td style="text-align:left;">Abre el menú de acciones de la selección actual, exactamente igual que el clic derecho.</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">Todas las ventanas</td><td style="text-align:left;">Bloqueado para evitar activar el menú del sistema en ventanas sin marco.</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">Ventanas Principal / Config</td><td style="text-align:left;">Cierra la ventana normalmente; bloqueado en las ventanas Rápida, Incrustada, Panel rápido, Vista previa, LocalSend y los diálogos internos de la aplicación.</td></tr></tbody></table><h2 id="_5-atajos-de-acciones-de-plugins-y-lista-negra" tabindex="-1">5. Atajos de acciones de plugins y lista negra <a class="header-anchor" href="#_5-atajos-de-acciones-de-plugins-y-lista-negra" aria-label="Permalink to &quot;5. Atajos de acciones de plugins y lista negra&quot;">​</a></h2><h3 id="atajos-de-acciones-de-plugins" tabindex="-1">Atajos de acciones de plugins <a class="header-anchor" href="#atajos-de-acciones-de-plugins" aria-label="Permalink to &quot;Atajos de acciones de plugins&quot;">​</a></h3><p>Las acciones de archivo integradas llegan con estos valores predeterminados: Cortar <code>Ctrl+X</code>, Copiar archivo <code>Ctrl+C</code>, Pegar <code>Ctrl+V</code>, Eliminar <code>Delete</code>, Eliminación permanente <code>Shift+Delete</code>, Copiar ruta completa <code>Ctrl+Shift+C</code>, Copiar nombre <code>Shift+C</code>, Mostrar en Explorador <code>Ctrl+Enter</code>, Ejecutar como administrador <code>Ctrl+Shift+Enter</code>.</p><p>Dos salvaguardas hacen que las teclas destructivas sean seguras bajo un cuadro de búsqueda. Una combinación solo llega a una acción cuando el cuadro de búsqueda <strong>no tiene texto seleccionado</strong>, así que <code>Ctrl+X</code> / <code>Ctrl+C</code> / <code>Ctrl+V</code> siguen cortando, copiando y pegando tu consulta como siempre. Una tecla aislada como <code>Delete</code> solo llega a una acción cuando el cursor <strong>ya está al final</strong> de la consulta, donde no le queda ningún carácter que borrar; en cualquier otra posición del texto sigue siendo una tecla de escritura. Y las dos acciones de borrado pasan por el <code>IFileOperation</code> propio del shell, así que el aviso nativo de &quot;¿mover a la Papelera de reciclaje?&quot; / &quot;¿eliminar definitivamente?&quot; sigue interponiéndose entre la tecla y los archivos. Reasigna o vacía cualquiera de ellas en <strong>Configuración → Atajos de teclado → Acciones de plugins</strong>.</p><h3 id="lista-negra-de-procesos-y-omision-en-pantalla-completa" tabindex="-1">Lista negra de procesos y omisión en pantalla completa <a class="header-anchor" href="#lista-negra-de-procesos-y-omision-en-pantalla-completa" aria-label="Permalink to &quot;Lista negra de procesos y omisión en pantalla completa&quot;">​</a></h3><ul><li><strong>Omisión automática en pantalla completa</strong>: Cuando una aplicación se ejecuta en pantalla completa exclusiva (como juegos 3D o reproductores de vídeo), Lertaro omite automáticamente todos los atajos globales para no interferir.</li><li><strong>Lista negra de procesos personalizada</strong>: Añade ejecutables en <a href="./settings/hotkeys-page.html#lista-negra-de-procesos"><strong>Configuración → Atajos de teclado</strong></a> (p. ej. <code>game.exe</code>) para silenciar los atajos mientras ese proceso esté en primer plano.</li></ul>',38)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
